#!/usr/bin/env python3
"""Native CadQuery->VTK preview, images show REAL v03 CAD generated by script."""
from pathlib import Path
import sys
import vtk
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'hardware'/'cad'))
import generate_v03 as v


def actor(shape,color,opacity=1):
    pts,tris=shape.val().tessellate(0.4,0.18)
    ps=vtk.vtkPoints()
    for p in pts: ps.InsertNextPoint(p.x,p.y,p.z)
    cells=vtk.vtkCellArray()
    for a,b,c in tris:
        item=vtk.vtkTriangle()
        for k,n in enumerate((a,b,c)):item.GetPointIds().SetId(k,n)
        cells.InsertNextCell(item)
    poly=vtk.vtkPolyData();poly.SetPoints(ps);poly.SetPolys(cells)
    normals=vtk.vtkPolyDataNormals();normals.SetInputData(poly);normals.ConsistencyOn();normals.AutoOrientNormalsOn();normals.SplittingOff()
    mapper=vtk.vtkPolyDataMapper();mapper.SetInputConnection(normals.GetOutputPort())
    a=vtk.vtkActor();a.SetMapper(mapper)
    a.GetProperty().SetColor(color);a.GetProperty().SetAmbient(0.25)
    a.GetProperty().SetDiffuse(0.73);a.GetProperty().SetSpecular(0.24);a.GetProperty().SetSpecularPower(30)
    a.GetProperty().SetOpacity(opacity)
    return a


def make_text(scene,text,x,y,size=25,color=(0.18,0.22,0.28)):
    item=vtk.vtkTextActor();item.SetInput(text);item.SetPosition(x,y)
    item.GetTextProperty().SetFontSize(size);item.GetTextProperty().SetBold(True)
    item.GetTextProperty().SetColor(*color);scene.AddActor2D(item)


def render(out:Path,exploded=False):
    width,height=1800,980
    sc=vtk.vtkRenderer();sc.SetBackground(.964,.975,.982);sc.SetBackground2(.83,.87,.90);sc.GradientBackgroundOn()
    # Place RA & DEC groups beside one another in common X dimension.
    for r,shift in [(v.RA,(0,-94,0)),(v.DEC,(0,108,0))]:
        gear=v.reducer_envelope(r)
        parts=[('gear',gear,(.69,.72,.76)),
               ('housing',v.housing(r),(.14,.43,.55)),
               ('output',v.output_adapter(r),(.91,.62,.26)),
               ('motor_slider',v.nema_motor_carrier(r),(.22,.28,.32)),
               ('bearing',v.bearing_bridge(r),(.44,.68,.78))]
        for name,solid,col in parts:
            if exploded:
                dz={'gear':17,'housing':0,'output':30,'motor_slider':-12,'bearing':-18}[name]
                solid=solid.translate((0,0,dz))
            a=actor(solid,col,opacity=0.78 if name=='gear' else 1)
            a.SetPosition(*shift);sc.AddActor(a)
    win=vtk.vtkRenderWindow();win.SetSize(width,height);win.OffScreenRenderingOn();win.AddRenderer(sc)
    cam=sc.GetActiveCamera();cam.SetPosition(310,-370,310);cam.SetFocalPoint(28,12,30);cam.SetViewUp(0,0,1)
    cam.ParallelProjectionOn();cam.SetParallelScale(177)
    make_text(sc,'OpenEQMount  /  V0.3  FDM REDUCER INTERFACE',55,930,30)
    make_text(sc,'RA: CSF-17-100-2UH     |     DEC: CSF-14-100-2UH',55,891,20,(.30,.39,.45))
    make_text(sc,'BENCH FIT ONLY  -  NOT LOAD RATED  /  NOT A COMPLETE MOUNT',55,48,21,(.60,.22,.18))
    sc.ResetCameraClippingRange();win.Render()
    grab=vtk.vtkWindowToImageFilter();grab.SetInput(win);grab.Update()
    write=vtk.vtkPNGWriter();write.SetFileName(str(out));write.SetInputConnection(grab.GetOutputPort());write.Write()
    win.Finalize()
    print(out)

if __name__=='__main__':
    p=ROOT/'hardware/cad/v03_generated'
    render(p/'OpenEQMount_V03_modules.png',False)
    render(p/'OpenEQMount_V03_exploded.png',True)
